from rdkit import Chem
from rdkit.Geometry import Point3D
import numpy as np, os, shutil
m=Chem.MolFromMolFile('optimized.mol',removeHs=False)
lines=open('refined.xyz').read().splitlines(); n=int(lines[0]); syms=[]; coords=[]
for l in lines[2:2+n]:
 p=l.split(); syms.append(p[0]); coords.append(list(map(float,p[1:4])))
a=np.array(coords)
assert n==m.GetNumAtoms()==118
assert syms==[x.GetSymbol() for x in m.GetAtoms()]
original={i:s for i,s in Chem.FindMolChiralCenters(m,includeUnassigned=True)}
c=m.GetConformer()
for i,xyz in enumerate(a): c.SetAtomPosition(i,Point3D(*xyz))
Chem.AssignAtomChiralTagsFromStructure(m,replaceExistingTags=True)
Chem.AssignStereochemistry(m,cleanIt=True,force=True)
actual={i:s for i,s in Chem.FindMolChiralCenters(m,includeUnassigned=True)}
print('Stereocenters preserved:',original==actual,'count:',len(original))
assert original==actual, (original,actual)
for b in m.GetBonds():
 i,j=b.GetBeginAtomIdx(),b.GetEndAtomIdx(); d=np.linalg.norm(a[i]-a[j]);
 if syms[i]=='H' or syms[j]=='H': assert 0.85<d<1.3, (i,j,d)
 else: assert 1.1<d<1.8,(i,j,d)
# Confirm hydrogen connectivity remains unchanged.
for i,atom in enumerate(m.GetAtoms()):
 if atom.GetSymbol()=='H':
  j=atom.GetNeighbors()[0].GetIdx()
  ds=np.linalg.norm(a[:51]-a[i],axis=1)
  assert np.argmin(ds)==j, (i,j,np.argmin(ds))
with open('answer.xyz','w') as f:
 f.write(f'{n}\nErythromycin A; explicit hydrogens; GFN2-xTB optimized; coordinates in angstroms\n')
 for s,(x,y,z) in zip(syms,a): f.write(f'{s:2s} {x: .10f} {y: .10f} {z: .10f}\n')
print('Verified:',os.path.abspath('answer.xyz'),os.path.getsize('answer.xyz'),'bytes')
